import { InputInputEventDetail, SearchbarInputEventDetail, ToggleChangeEventDetail } from '@ionic/core/dist/types/components';

const ITEMS_PER_PAGE = 20;

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<Omit<Supplier, 'supplierId' | 'created_At' | 'updated_at'>>({
    companyId: companyId,
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: '1',
  });
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<Supplier | null>(null);
  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(1);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);

  const [popoverState, setPopoverState] = useState<{showAlertPopover: boolean; showMailPopover: boolean; event?: Event;}>(
    { showAlertPopover: false, showMailPopover: false }
  );

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  useEffect(() => {
    if (companyId) {
      loadSuppliers(true);
    }
  }, [companyId]);

  useEffect(() => {
    const lowercasedFilter = searchText.toLowerCase();
    const filtered = suppliers.filter(supplier =>
      supplier.supplierName.toLowerCase().includes(lowercasedFilter) ||
      (supplier.contactName?.toLowerCase().includes(lowercasedFilter)) ||
      (supplier.email?.toLowerCase().includes(lowercasedFilter))
    );
    setFilteredSuppliers(filtered.slice(0, ITEMS_PER_PAGE));
    setPage(1);
    setInfiniteDisabled(filtered.length <= ITEMS_PER_PAGE);
  }, [searchText, suppliers]);

  const loadSuppliers = async (initialLoad: boolean = false, refresher?: CustomEvent<RefresherEventDetail>) => {
    if (initialLoad) setLoading(true);
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      setFilteredSuppliers(data.slice(0, ITEMS_PER_PAGE));
      setPage(1);
      setInfiniteDisabled(data.length <= ITEMS_PER_PAGE);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading suppliers');
    } finally {
      setLoading(false);
      refresher?.detail.complete();
    }
  };

  const loadMoreItems = async () => {
    const newPage = page + 1;
    const startIndex = (newPage - 1) * ITEMS_PER_PAGE;
    const endIndex = newPage * ITEMS_PER_PAGE;
    const newItems = filteredSuppliers.slice(startIndex, endIndex);

    if (newItems.length > 0) {
      setFilteredSuppliers(prev => [...prev, ...newItems]);
      setPage(newPage);
    } else {
      setInfiniteDisabled(true);
    }
  };

  const handleAdd = () => {
    setSelectedSupplier(null);
    setFormState({
      companyId: companyId,
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: '1',
    });
    setShowModal(true);
  };

  const handleEdit = (supplier: Supplier) => {
    setSelectedSupplier(supplier);
    setFormState({
      companyId: supplier.companyId,
      supplierName: supplier.supplierName,
      contactName: supplier.contactName || '',
      phone: supplier.phone || '',
      email: supplier.email || '',
      address: supplier.address || '',
      active: supplier.active,
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      if (!formState.supplierName) {
        throw new Error('Supplier Name is required.');
      }
      if (!formState.active) {
        throw new Error('Active status is required.');
      }

      if (selectedSupplier) {
        await updateSupplier(selectedSupplier.supplierId, formState, companyId);
        setError('Supplier updated successfully!');
      } else {
        await createSupplier(formState);
        setError('Supplier created successfully!');
      }
      setShowModal(false);
      loadSuppliers(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error saving supplier.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (supplier: Supplier) => {
    setSupplierToDelete(supplier);
    setShowDeleteAlert(true);
  };

  const handleDelete = async () => {
    if (supplierToDelete) {
      setSaving(true);
      try {
        await deleteSupplier(supplierToDelete.supplierId, companyId);
        setError('Supplier deleted successfully!');
        loadSuppliers(true);
      } catch (err) {
        setError((err as Error).message ?? 'Error deleting supplier.');
      } finally {
        setSaving(false);
        setSupplierToDelete(null);
      }
    }
