      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="supplier-page">
        <IonRefresher slot="fixed" onIonRefresh={(ev: CustomEvent<RefresherEventDetail>) => loadSuppliers(true, ev)}>
          <IonRefresherContent></IonRefresherContent>
        </IonRefresher>

        <IonLoading isOpen={loading} message={'Loading Suppliers...'} />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.includes('Error') ? 'danger' : 'success'}
        />

        <IonSearchbar
          placeholder="Search Suppliers"
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
          debounce={300}
        />

        <IonList>
          {filteredSuppliers.map((supplier) => (
            <IonItem key={supplier.supplierId}>
              <IonLabel>
